lab.solution:
def average(scores):
    if not scores:
        raise ValueError('At least one score is required')
    return sum(int(score) for score in scores) / len(scores)

assert average(['4', '6']) == 5
try:
    average([])
except ValueError as error:
    assert str(error) == 'At least one score is required'
else:
    raise AssertionError('Expected ValueError for empty scores')
print('normal and empty cases checked')
